#!/usr/bin/env bash
# Question 1: Unhealthy worker. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

[[ "$CKA_NODE" == "${Q1_NODE}" ]] || exit 0

case "${Q1_FAULT}" in
  kubelet-config-invalid)
    sed -i -E 's/^kind: KubeletConfiguration$/kind: KubeletConfig/' /var/lib/kubelet/config.yaml
    grep -qE -- '^kind: KubeletConfig$' /var/lib/kubelet/config.yaml || { echo "could not edit /var/lib/kubelet/config.yaml" >&2; exit 1; }
    systemctl restart kubelet || true
    ;;
esac
